29	/**
30	 * HoodieRollbackRequest in HoodieRollbackPlan (avro pojo) is not operable directly within spark parallel engine.
31	 * Hence converting the same to this {@link SerializableHoodieRollbackRequest} and then using it within spark.parallelize.
32	 */
33	public class SerializableHoodieRollbackRequest implements Serializable {
34	
35	  private final String partitionPath;
36	  private final String fileId;
37	  private final String latestBaseInstant;
38	  private final List<String> filesToBeDeleted = new ArrayList<>();
39	  private final Map<String, Long> logBlocksToBeDeleted = new HashMap<>();
40	
41	  public SerializableHoodieRollbackRequest(HoodieRollbackRequest rollbackRequest) {
42	    this.partitionPath = rollbackRequest.getPartitionPath();
43	    this.fileId = rollbackRequest.getFileId();
44	    this.latestBaseInstant = rollbackRequest.getLatestBaseInstant();
45	    this.filesToBeDeleted.addAll(rollbackRequest.getFilesToBeDeleted());
46	    this.logBlocksToBeDeleted.putAll(rollbackRequest.getLogBlocksToBeDeleted());
47	  }
48	
49	  public String getPartitionPath() {
50	    return partitionPath;
