  /**
   * Groups the rollback requests based on the file group (partition path, file id and latest base instant) so that
   * each file group ends up with at most two non-empty rollback requests: one carrying the base (or log) files to be
   * deleted and one carrying the log blocks to be rolled back through a rollback command block.
   *
   * <p>Log-only requests (i.e. requests with an empty {@code filesToBeDeleted}) that belong to the same file group are
   * merged into a single request with their {@code logBlocksToBeDeleted} combined. Requests that carry files to be
   * deleted are never merged with log-only requests, and a request that carries both files to be deleted and log blocks
   * is split into a base-file-only request and a log-only request.
   *
   * @param rollbackRequests list of {@link HoodieRollbackRequest} to group.
   * @return grouped list of {@link HoodieRollbackRequest}.
   */
  public static List<HoodieRollbackRequest> groupRollbackRequestsBasedOnFileGroup(List<HoodieRollbackRequest> rollbackRequests) {
    List<HoodieRollbackRequest> result = new ArrayList<>();
    // key -> merged log-only rollback request for the file group.
    Map<String, HoodieRollbackRequest> logRequestsByFileGroup = new HashMap<>();
    for (HoodieRollbackRequest rollbackRequest : rollbackRequests) {
      String partitionPath = rollbackRequest.getPartitionPath() == null ? "" : rollbackRequest.getPartitionPath();
      String fileId = rollbackRequest.getFileId();
      String latestBaseInstant = rollbackRequest.getLatestBaseInstant();
      List<String> filesToBeDeleted = rollbackRequest.getFilesToBeDeleted();
      Map<String, Long> logBlocksToBeDeleted = rollbackRequest.getLogBlocksToBeDeleted();
      boolean hasFilesToBeDeleted = filesToBeDeleted != null && !filesToBeDeleted.isEmpty();
      boolean hasLogBlocksToBeDeleted = logBlocksToBeDeleted != null && !logBlocksToBeDeleted.isEmpty();

      if (hasFilesToBeDeleted) {
        // Base/log files to be deleted are kept in their own request and never merged with log-only requests.
        result.add(new HoodieRollbackRequest(partitionPath, fileId, latestBaseInstant,
            new ArrayList<>(filesToBeDeleted), new HashMap<>()));
      }
      if (hasLogBlocksToBeDeleted) {
        String key = partitionPath + "|" + fileId + "|" + latestBaseInstant;
        HoodieRollbackRequest merged = logRequestsByFileGroup.get(key);
        if (merged == null) {
          logRequestsByFileGroup.put(key, new HoodieRollbackRequest(partitionPath, fileId, latestBaseInstant,
              new ArrayList<>(), new HashMap<>(logBlocksToBeDeleted)));
        } else {
          merged.getLogBlocksToBeDeleted().putAll(logBlocksToBeDeleted);
        }
      }
      if (!hasFilesToBeDeleted && !hasLogBlocksToBeDeleted) {
        // Preserve empty rollback requests so that empty rollback stats can still be collected.
        result.add(new HoodieRollbackRequest(partitionPath, fileId, latestBaseInstant, new ArrayList<>(), new HashMap<>()));
      }
    }
    result.addAll(logRequestsByFileGroup.values());
    return result;
  }

